// The text of `generated/global-variables.md` (VR-1, FR-025): a short note for the reader, then the one table.
import { refuse, succeed, type Result } from '#shared/domain/result/Result.ts';
import { renderVariableTable, type RowViolation, type VariableRow } from '#rendering/domain/variables/VariableTable.ts';

const INTRODUCTION = [
  '# Global variables',
  '',
  'Written by the installer on this machine from the `variables:` list of each enabled component and from the values V stored.',
  'Change a value with the installer `set NAME=value` command, then run `install`; do not edit this file.',
].join('\n');

/**
 * Writes the whole file: a title and a note, a blank line, the table, and one final line ending. The same rows give the same bytes.
 *
 * @param rows - the rows, the computed variable first
 * @returns the file text, or every cell that must not be printed
 */
export function renderGlobalVariablesFile(rows: readonly VariableRow[]): Result<string, readonly RowViolation[]> {
  const table = renderVariableTable(rows);
  return table.ok ? succeed(`${INTRODUCTION}\n\n${table.value}\n`) : refuse(table.error);
}
